import { AppUI, Textarea, row, tabs } from "march/ui"
import { edit, eye } from "march/icons"

// haiku atölyesi: solda taslak, sağda önizleme; iki panel aynı sinyali okur, yerleşimi sürükleyerek değiştir
export function HaikuStudio() {
  let $text = "sessiz bir havuz\nkurbağa atlar içine\nsuyun sesi"
  const lines = () => $text.split("\n").filter(Boolean)
  const panels = [
    { id: "draft", title: "Taslak", icon: edit, content: () => <div sx={{ p: 2 }}><Textarea label="Haiku" bind:value={$text} rows={4} /></div> },
    { id: "view", title: "Önizleme", icon: eye, content: () => <div sx={{ p: 3, flex: "col", gap: 1 }}>
      {() => lines().map((l, i) => <span sx={{ text: i === 1 ? ["lg", "bold"] : "md" }}>{l}</span>)}
      <span sx={{ text: "xs", color: "muted" }}>{() => lines().length} dize</span>
    </div> },
  ]
  return <div style={{ height: "18rem" }}>
    <AppUI title="haiku-atölyesi" description="5 · 7 · 5" panels={panels} layout={row([0.5, tabs("draft")], [0.5, tabs("view")])} commands={false} />
  </div>
}

import { AppUI, Button, StatusBar, Textarea, row, col, tabs, toast } from "march/ui"
import { database, play, list, terminal } from "march/icons"

// gerçek hayattan: küçük bir veri tabanı konsolu. Solda tablolar, ortada sorgu, altta sonuç; üst çubukta Çalıştır,
// altta durum çubuğu. Yerleşim menüsünde iki hazır düzen var.
const TABLES = ["users", "orders", "products"]

export function QueryConsole() {
  let $sql = "select * from users limit 3"
  let $rows: string[] = []
  const run = () => { $rows = ["1 · Ada", "2 · Deniz", "3 · Ece"]; toast("Sorgu çalıştı (3 satır)") }
  const panels = [
    { id: "tables", title: "Tablolar", icon: database, content: () => <div sx={{ p: 2, flex: "col", gap: 1 }}>
      {TABLES.map((t) => <Button size="sm" variant="ghost" on:click={() => $sql = `select * from ${t} limit 3`}>{t}</Button>)}
    </div> },
    { id: "query", title: "Sorgu", icon: terminal, content: () => <div sx={{ p: 2 }}><Textarea label="SQL" bind:value={$sql} rows={3} /></div> },
    { id: "result", title: "Sonuç", icon: list, badge: () => $rows.length || null, content: () => <div sx={{ p: 2, flex: "col", gap: 1 }}>
      {() => $rows.length ? $rows.map((r) => <code>{r}</code>) : <span sx={{ color: "muted" }}>Henüz sonuç yok</span>}
    </div> },
  ]
  return <div style={{ height: "20rem" }}>
    <AppUI title="veritabanı" description="yerel kopya" panels={panels} commands={false}
      presets={{
        work: { title: "Çalışma", tree: () => row([0.25, tabs("tables")], [0.75, col([0.5, tabs("query")], [0.5, tabs("result")])]) },
        focus: { title: "Odak", tree: () => tabs(["query", "result", "tables"]) },
      }}
      tools={<Button size="sm" icon={play} on:click={run}>Çalıştır</Button>}
      status={<StatusBar items={[{ id: "db", text: "bağlı: demo.db", tone: "success" }, { id: "rows", text: () => `${$rows.length} satır`, side: "end" }]} />} />
  </div>
}

import { AppUI, ActivityBar, StatusBar, Button, definePlugin, row, col, tabs, type AppKit, type DockApi } from "march/ui"
import { fileText, folder, grid, terminal, star } from "march/icons"

// AppUI'nin bütün özellikleri: paneller (biri dosya), eklenti (".md" dosya türü + kendi paneli), başlık, açıklama ve
// işareti, araçlar, yan (ActivityBar) ve durum (StatusBar) yuvaları, üst çubuk, Yerleşim düğmesinin adı / ikonu, kit;
// altındaki DockLayout'un da hepsi: hazır düzenler, başlangıç düzeni, düzen ağacı, saklama, ad, komut öneki, api,
// onChange, onClose, grup düğmeleri, dar kip, hareket, ikonlar, metinler, id, sınıf.
const mdPlugin = definePlugin({ id: "lab.md", title: "Markdown", activate(ctx) {
  ctx.fileType({ id: "md", match: /\.md$/, mount: (f) => <article sx={{ p: 2 }}><strong>{() => f.text().split("\n")[0]}</strong></article> })
  ctx.panel({ id: "stars", title: "Yıldızlar", icon: star, content: () => <p sx={{ p: 2 }}>Eklentinin paneli</p> })
} })

export function AppUILab() {
  let $view: string | null = "files"
  let $bar = true
  let $changes = 0
  let $plugins = 0
  let $closed = ""
  const mem = new Map<string, unknown>()
  let dock: DockApi | undefined
  const panels = [
    { id: "files", title: "Dosyalar", icon: folder, min: [120, 80] as [number, number], content: () => <p sx={{ p: 2 }}>src/ · README.md</p> },
    { id: "readme", title: "README.md", icon: fileText, file: { path: "README.md", text: () => "# Merhaba AppUI\nbir dosya paneli" } },
    { id: "log", title: "Günlük", icon: terminal, closable: true, content: () => <p sx={{ p: 2 }}>derleme tamam</p> },
  ]
  return <div style={{ height: "24rem" }}>
    <AppUI
      panels={panels}
      plugins={[mdPlugin]}
      title="lab-ide"
      description="bütün özellikler"
      descriptionMark="#"
      tools={<Button size="sm" variant="secondary" on:click={() => dock?.open("log")}>Günlüğü aç</Button>}
      side={<ActivityBar items={[{ id: "files", label: "Dosyalar", icon: folder }, { id: "log", label: "Günlük", icon: terminal }]} value={$view} onChange={(id) => { $view = id; if (id) dock?.open(id) }} />}
      status={<StatusBar items={[{ id: "bar", text: () => ($bar ? "Çubuğu gizle" : "Çubuğu göster"), onSelect: () => $bar = !$bar }, { id: "ch", text: () => `değişiklik: ${$changes}` }, { id: "pl", text: () => `eklenti paneli: ${$plugins}`, side: "end" }, { id: "cl", text: () => $closed ? `kapandı: ${$closed}` : "açık", side: "end" }]} />}
      bar={$bar}
      layoutLabel="Düzenler"
      layoutMenu
      layoutIcon={grid}
      kit={(k: AppKit) => $plugins = k.panels().length}
      presets={{
        main: { title: "Ana düzen", tree: () => row([0.25, tabs("files")], [0.75, col([0.6, tabs(["readme", "stars"])], [0.4, tabs("log")])]) },
        flat: { title: "Tek grup", tree: () => tabs(["readme", "files", "log", "stars"]) },
      }}
      preset="main"
      layout={tabs(["files", "readme", "log", "stars"])}
      persist="lab-app-ui"
      storage={{ get: (k) => mem.get(k), set: (k, v) => { mem.set(k, v) } }}
      label="Lab çalışma alanı"
      commands="labApp"
      api={(a) => dock = a}
      onChange={() => $changes++}
      onClose={(id) => { $closed = id; return false }}
      actions={["maximize", "collapse", "menu"]}
      narrow={320}
      narrowTabs="bottom"
      motion={false}
      icons={{ menu: "⋯", maximize: "▢", restore: "❐", collapse: "–" }}
      labels={{ menu: "Seçenekler", maximize: "Tam boy", restore: "Eski boyut", collapse: "Daralt", panels: "Paneller", strip: "Şerit" }}
      id="lab-app"
      class="lab-app"
    />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { AppUILab } from "./AppUILab.tsx"

// AppUILab'in testleri: üst çubuk, eklentinin dosya türü ve paneli, yuvalar, düğmeler
test("üst çubuk: başlık, kendi işaretli açıklama, Düzenler düğmesi, id", () => {
  const s = renderTest(() => <AppUILab />)
  expect(s.get(".lab-app .m-app-title")?.textContent).toBe("lab-ide")
  expect(s.get(".lab-app .m-app-desc")?.textContent).toContain("# bütün özellikler")
  expect(s.find("Düzenler")).toBeTruthy()
  expect(s.get("#lab-app")).toBeTruthy()
})

test("eklenti: .md dosyasını kendi türü çizer, kendi paneli de gelir", () => {
  const s = renderTest(() => <AppUILab />)
  expect(s.get(".lab-app .m-app-file article")?.textContent).toBe("# Merhaba AppUI")
  expect(s.sees("Yıldızlar")).toBe(true)
  expect(s.sees("eklenti paneli: 1")).toBe(true)
})

test("yan ve durum yuvaları yerinde", () => {
  const s = renderTest(() => <AppUILab />)
  expect(s.get(".lab-app .m-app-main")?.firstElementChild?.classList.contains("m-app-body")).toBe(false)
  expect(s.sees("değişiklik:")).toBe(true)
})

test("durum çubuğundaki düğme üst çubuğu gizler ve geri getirir", async () => {
  const s = renderTest(() => <AppUILab />)
  await s.click("Çubuğu gizle")
  expect(s.get(".lab-app .m-app-bar")).toBe(null)
  await s.click("Çubuğu göster")
  expect(s.get(".lab-app .m-app-bar")).toBeTruthy()
})
